/**
 * Filesystem-first evals for agent-serve projects.
 *
 * Author cases under evals/ as `*.eval.ts` files with {@link defineEval}.
 * One file may hold a single datapoint (`test`) or many (`cases`). Drive the
 * agent with `t.send(...)` and assert with `t.succeeded()`, `t.calledTool()`,
 * `t.messageIncludes(...)`, or `t.check(value, includes(...))`.
 *
 * ```ts
 * import { defineEval, includes } from "@grok/agent-sdk/evals";
 *
 * // One datapoint — id is the file path (evals/weather/nyc.eval.ts → weather/nyc)
 * export default defineEval({
 *   description: "Weather tool is used for temperature questions.",
 *   async test(t) {
 *     await t.send("What's the temperature in NYC?");
 *     t.succeeded();
 *     t.calledTool("get_weather");
 *     t.check(t.reply, includes(/°|F|C/));
 *   },
 * });
 *
 * // Many datapoints in one file — ids are <fileId>/<case.id>
 * // evals/weather.eval.ts → weather/nyc, weather/paris
 * export default defineEval({
 *   tags: ["smoke", "weather"],
 *   cases: [
 *     {
 *       id: "nyc",
 *       async test(t) {
 *         await t.send("What's the temperature in NYC?");
 *         t.succeeded();
 *         t.calledTool("get_weather");
 *       },
 *     },
 *     {
 *       id: "paris",
 *       async test(t) {
 *         await t.send("What's the weather in Paris?");
 *         t.succeeded();
 *         t.calledTool("get_weather");
 *       },
 *     },
 *   ],
 * });
 * ```
 *
 * ## Severity: gates and scores
 *
 * Every assertion returns a chainable handle, so severity rides on the
 * assertion instead of a separate thresholds map. Gates are hard (a miss fails
 * the eval and `eval` exits non-zero); soft assertions are tracked scores that
 * mark the eval `scored` and only fail the build under `--strict`:
 *
 * ```ts
 * t.succeeded();                                        // gate (default)
 * t.calledTool("get_weather").soft();                   // tracked, no gate
 * t.check(t.reply, similarity("Sunny, 72F")).atLeast(0.8);
 * t.judge.closedQA("cites a source").atLeast(0.6);      // LLM-graded
 * ```
 *
 * Matchers narrow tool assertions (`{ input, output, status, count }` accept a
 * literal, a RegExp, or a predicate), and each turn returned by `t.send(...)`
 * carries the same vocabulary scoped to that turn.
 */
import { normalizePositiveInt } from "./internal/bounded-int.js";
import { brandDefinition } from "./internal/brand.js";
export { computeVerdict, verdictFailsRun } from "./evals/assertions.js";
export { equals, includes, matches, normalizedSimilarity, satisfies, similarity, } from "./evals/expect.js";
// A custom judge built on `t.judge.model` embeds the same attacker-controlled
// agent output the built-in graders do, so it needs the same two protections.
export { EVAL_JUDGE_INJECTION_GUARD, fenceUntrusted } from "./evals/judge.js";
export { deriveRunFacts } from "./evals/run-facts.js";
/** Hard ceiling for {@link EvalConfig.iterations} / case `iterations`. */
export const EVAL_MAX_ITERATIONS = 100;
/**
 * Author an eval file. The path under `evals/` is the file id:
 * `evals/weather.eval.ts` → `weather`. With a single `test`, that is also
 * the case id. With `cases`, each datapoint is `<fileId>/<case.id>`.
 */
export function normalizeEvalIterations(value) {
    return normalizePositiveInt(value, {
        label: "defineEval: iterations",
        max: EVAL_MAX_ITERATIONS,
    });
}
export function defineEval(config) {
    const hasTest = typeof config.test === "function";
    const hasCases = config.cases !== undefined;
    if (hasTest && hasCases) {
        throw new Error("defineEval: set either test or cases, not both");
    }
    if (!hasTest && !hasCases) {
        throw new Error("defineEval requires test(t) or a non-empty cases array");
    }
    if (config.iterations !== undefined) {
        normalizeEvalIterations(config.iterations);
    }
    if (hasCases) {
        if (!Array.isArray(config.cases) || config.cases.length === 0) {
            throw new Error("defineEval: cases must be a non-empty array");
        }
        const seen = new Set();
        for (const datapoint of config.cases) {
            validateDatapointId(datapoint.id);
            if (seen.has(datapoint.id)) {
                throw new Error(`defineEval: duplicate case id ${JSON.stringify(datapoint.id)}`);
            }
            seen.add(datapoint.id);
            if (typeof datapoint.test !== "function") {
                throw new Error(`defineEval: cases[${JSON.stringify(datapoint.id)}] requires test(t)`);
            }
            if (datapoint.iterations !== undefined) {
                normalizeEvalIterations(datapoint.iterations);
            }
        }
    }
    return brandDefinition("eval", config);
}
function validateDatapointId(id) {
    if (typeof id !== "string" || id.length === 0) {
        throw new Error("defineEval: each case needs a non-empty string id");
    }
    if (id.includes("/") || id.includes("\\") || id.includes("..")) {
        throw new Error(`defineEval: case id must be a single path segment (got ${JSON.stringify(id)})`);
    }
}
/**
 * Expand a file-level definition into runnable datapoints.
 * Exported for tests and tooling.
 *
 * When `iterations` > 1, each authored datapoint expands to
 * `<fileId>/<case.id>/1` … `<fileId>/<case.id>/<n>` (single-test files
 * expand to `<fileId>/1` … `<fileId>/<n>`).
 */
export function expandEvalDefinition(fileId, definition) {
    if (definition.cases !== undefined) {
        return definition.cases.flatMap((datapoint) => {
            const description = datapoint.description ?? definition.description;
            const timeoutMs = datapoint.timeoutMs ?? definition.timeoutMs;
            const iterations = normalizeEvalIterations(datapoint.iterations ?? definition.iterations ?? 1);
            const metadata = datapoint.metadata === undefined && definition.metadata === undefined
                ? undefined
                : { ...definition.metadata, ...datapoint.metadata };
            return expandIterations({
                baseId: `${fileId}/${datapoint.id}`,
                description,
                tags: datapoint.tags ?? definition.tags,
                timeoutMs,
                iterations,
                metadata,
                judge: datapoint.judge ?? definition.judge,
                reporters: mergeReporters(definition.reporters, datapoint.reporters),
                test: datapoint.test,
            });
        });
    }
    if (typeof definition.test !== "function") {
        throw new Error(`defineEval(${fileId}): missing test(t)`);
    }
    const iterations = normalizeEvalIterations(definition.iterations ?? 1);
    return expandIterations({
        baseId: fileId,
        description: definition.description,
        tags: definition.tags,
        timeoutMs: definition.timeoutMs,
        iterations,
        metadata: definition.metadata,
        judge: definition.judge,
        reporters: definition.reporters,
        test: definition.test,
    });
}
/** Union file-level and case-level reporters, keeping each instance once. */
function mergeReporters(fileLevel, caseLevel) {
    if (fileLevel === undefined) {
        return caseLevel;
    }
    if (caseLevel === undefined) {
        return fileLevel;
    }
    return [...new Set([...fileLevel, ...caseLevel])];
}
function expandIterations(args) {
    const out = [];
    for (let iteration = 1; iteration <= args.iterations; iteration++) {
        const id = args.iterations === 1 ? args.baseId : `${args.baseId}/${iteration}`;
        const description = args.iterations === 1 || args.description === undefined
            ? args.description
            : `${args.description} (iteration ${iteration}/${args.iterations})`;
        out.push({
            id,
            definition: brandDefinition("eval", {
                ...(description !== undefined ? { description } : {}),
                ...(args.tags !== undefined ? { tags: args.tags } : {}),
                ...(args.timeoutMs !== undefined ? { timeoutMs: args.timeoutMs } : {}),
                metadata: args.metadata,
                judge: args.judge,
                reporters: args.reporters,
                iterations: args.iterations,
                iteration,
                test: args.test,
            }),
        });
    }
    return out;
}
/**
 * Whether a discovered case id matches a CLI filter.
 * - exact datapoint: `weather/nyc`
 * - whole file / prefix: `weather` selects `weather`, `weather/nyc`, …
 * - multiple filters: OR
 */
export function matchesEvalIdFilter(caseId, filter) {
    return caseId === filter || caseId.startsWith(`${filter}/`);
}
/**
 * Tag for suite-aggregator datapoints that wait on sibling cases from the
 * same eval file (e.g. `benchmark/overall`). Selecting a summary case
 * alone expands the batch to the whole file via
 * {@link expandSummarySuiteSelection}.
 */
export const EVAL_SUMMARY_TAG = "summary";
/** True when `tags` marks a suite-aggregator case. */
export function isEvalSummaryCase(tags) {
    return tags?.includes(EVAL_SUMMARY_TAG) ?? false;
}
/**
 * If `selected` includes any summary-tagged suite aggregator, pull in every
 * other datapoint from the same `fileId` so the aggregator is not run alone.
 * Preserves discovery order from `all`.
 */
export function expandSummarySuiteSelection(all, selected, isSummary) {
    const fileIdsNeedingSuite = new Set(selected.filter((item) => isSummary(item)).map((item) => item.fileId));
    if (fileIdsNeedingSuite.size === 0) {
        return [...selected];
    }
    const selectedIds = new Set(selected.map((item) => item.id));
    const extras = all.filter((item) => fileIdsNeedingSuite.has(item.fileId) && !selectedIds.has(item.id));
    if (extras.length === 0) {
        return [...selected];
    }
    const want = new Set([...selectedIds, ...extras.map((item) => item.id)]);
    return all.filter((item) => want.has(item.id));
}
/**
 * Hard ceiling for concurrent eval cases.
 *
 * Each case issues model provider requests; unbounded parallelism would
 * overwhelm provider rate limits and exhaust local API quota.
 */
export const EVAL_MAX_CONCURRENCY_LIMIT = 200;
/** Default playground batches kept in the serve process when `maxPlaygroundRuns` is omitted. */
export const EVAL_DEFAULT_MAX_PLAYGROUND_RUNS = 20;
/** Hard ceiling for {@link EvalConfigFile.maxPlaygroundRuns}. */
export const EVAL_MAX_PLAYGROUND_RUNS = 500;
/**
 * Defaults for every eval under `evals/` (`evals/evals.config.ts`).
 * `maxConcurrency` is required (1–{@link EVAL_MAX_CONCURRENCY_LIMIT}).
 *
 * Playground batches default to **in-memory only**; author an `evals`
 * table in `agent/storage.ts` (`defineStorage`) to survive serve restart.
 */
export function defineEvalConfig(config) {
    return {
        ...(config.timeoutMs === undefined ? {} : { timeoutMs: config.timeoutMs }),
        maxConcurrency: normalizeEvalMaxConcurrency(config.maxConcurrency),
        maxPlaygroundRuns: normalizeEvalMaxPlaygroundRuns(config.maxPlaygroundRuns ?? EVAL_DEFAULT_MAX_PLAYGROUND_RUNS),
        judge: config.judge,
        reporters: config.reporters,
    };
}
/**
 * Validate and enforce the hard concurrency ceiling.
 */
export function normalizeEvalMaxConcurrency(value) {
    return normalizePositiveInt(value, {
        label: "evals.config.ts: maxConcurrency",
        max: EVAL_MAX_CONCURRENCY_LIMIT,
        maxMessage: `evals.config.ts: maxConcurrency ${String(value)} exceeds the hard limit of ${EVAL_MAX_CONCURRENCY_LIMIT} (model provider request limits)`,
    });
}
/** Validate {@link EvalConfigFile.maxPlaygroundRuns}. */
export function normalizeEvalMaxPlaygroundRuns(value) {
    return normalizePositiveInt(value, {
        label: "evals.config.ts: maxPlaygroundRuns",
        max: EVAL_MAX_PLAYGROUND_RUNS,
    });
}
/**
 * Effective playground history window. Invalid values fall back to
 * {@link EVAL_DEFAULT_MAX_PLAYGROUND_RUNS} (same as a missing field).
 */
export function resolveEvalMaxPlaygroundRuns(value) {
    if (value === undefined) {
        return EVAL_DEFAULT_MAX_PLAYGROUND_RUNS;
    }
    try {
        return normalizeEvalMaxPlaygroundRuns(value);
    }
    catch {
        return EVAL_DEFAULT_MAX_PLAYGROUND_RUNS;
    }
}
